-- TPC-DS Test_Query Query 378
-- Based on: query48.tpl (medium)
-- Variation: 80

select sum (ss_quantity) from store_sales, store, customer_demographics, customer_address, date_dim where s_store_sk = ss_store_sk and  ss_sold_date_sk = d_date_sk and d_year = 2056 and ( ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.2' and cd_education_status = 'ES.1' and ss_sales_price between 100.1 and 150.1 ) or ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.2' and cd_education_status = 'ES.1' and ss_sales_price between 50.1 and 100.1 ) or ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.2' and cd_education_status = 'ES.2' and ss_sales_price between 150.1 and 200.1 ) ) and ( ( ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.2', 'STATE.1', 'STATE.2') and ss_net_profit between 2 and 2097 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.4', 'STATE.4', 'STATE.4') and ss_net_profit between 159 and 2999 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.7', 'STATE.8', 'STATE.7') and ss_net_profit between 49 and 25000 ) );
